// Typed access to the artifact-derived data. Nothing in this file is a
// result: numbers live in src/data/benchmark.json, which is generated by
// scripts/build-data.mjs from the repository's saved release artifacts.
import raw from "../data/benchmark.json";

export type ModelId = "logreg" | "xgboost" | "mlp" | "deep_mlp" | "resnet_mlp";
export type GroupId = "low_level" | "high_level" | "all";
export type BudgetId = "250k" | "1m" | "2.5m";

export interface Run {
  run: string;
  model: ModelId;
  group: GroupId;
  rocAuc: number;
  prAuc: number;
  brier: number;
  ece: number;
  trainSeconds: number;
  epochs: number | null;
  parameters: number | null;
}

interface SplitChecks {
  rows: number;
  signal_fraction: number;
  split_sizes: { train: number; validation: number; test: number };
  indices_disjoint: boolean;
  covers_every_row: boolean;
  duplicate_events_in_sample: number;
  events_shared_by_train_and_test: number;
}

interface Benchmark {
  run: {
    seed: number;
    sourceRows: number;
    duplicateRowsRemoved: number;
    gpu: string;
    started: string;
    finished: string;
    determinism: { device: string; epochs: number; max_abs_probability_diff: number; identical: boolean };
  };
  budgets: Record<BudgetId, { rows: number; splitChecks: SplitChecks; runs: Run[] }>;
  configs: Record<ModelId, { family: string; config: Record<string, unknown>; parameterCount: number | null; schemaVersion: string; splitProtocol: string }>;
  operatingPoints: Record<ModelId, { validationThreshold: number; testSignalEfficiency: number; testBackgroundRejection: number } | null>;
  roc: Record<ModelId, [number, number][]>;
  accuracy: Record<string, number>;
  features: { name: string; group: "low_level" | "high_level"; description: string }[];
}

export const data = raw as unknown as Benchmark;

export const MODEL_ORDER: ModelId[] = ["logreg", "xgboost", "mlp", "deep_mlp", "resnet_mlp"];
export const BUDGET_ORDER: BudgetId[] = ["250k", "1m", "2.5m"];
export const BUDGET_LABEL: Record<BudgetId, string> = { "250k": "250k", "1m": "1M", "2.5m": "2.5M" };

// Categorical colours, fixed per model in every chart. Checked with the
// dataviz palette validator against the dark surface (CVD and contrast pass).
export const MODEL: Record<ModelId, { label: string; short: string; color: string }> = {
  logreg: { label: "Logistic Regression", short: "LogReg", color: "#7890D8" },
  xgboost: { label: "XGBoost", short: "XGBoost", color: "#BF8A2C" },
  mlp: { label: "Compact MLP", short: "Compact MLP", color: "#D45F9B" },
  deep_mlp: { label: "Deep MLP", short: "Deep MLP", color: "#8F74E8" },
  resnet_mlp: { label: "Residual MLP", short: "Residual MLP", color: "#28A6B9" },
};

export function getRun(budget: BudgetId, model: ModelId, group: GroupId): Run {
  const r = data.budgets[budget].runs.find((x) => x.model === model && x.group === group);
  if (!r) throw new Error(`no run for ${budget}/${model}/${group}`);
  return r;
}

export const f4 = (x: number) => x.toFixed(4);
export const int = (x: number) => x.toLocaleString("en-US");
export const cfg = <T,>(model: ModelId, key: string) => data.configs[model].config[key] as T;
